//   Course Clips/ 4 - Boo's Mansion/ Left (4-4, 4-7)/4-4 Back GFX / layer 'Layer 7' / frame 3
void frame_4388_0(Activation& scope) {
    stop();
    //this.createEmptyMovieClip("soundclip", this.getNextHighestDepth());
    if (_root["Course"]["Char"]["_y"] - scope["_y"] < -500) {
        _root["soundcrank"] = new_(Sound, scope.self);
        _root["soundcrank"]["attachSound"]("crank");
        _root["soundcrank"]["start"](0, 1);
        _root["soundcrank"]["setVolume"](_root["BgVolume"] * 0.3);
    }
    _root["soundcrank"]["onSoundComplete"] = scope.function([](Activation& scope) -> Value {
        if (_root["Course"]["Char"]["_y"] - scope["_y"] < -500) {
            //soundclip = new Sound(this);
            _root["soundcrank"]["attachSound"]("crank");
            _root["soundcrank"]["start"](0, 1);
            _root["soundcrank"]["setVolume"](_root["BgVolume"] * 0.3);
        }
        return undefined;
    });
    stop();
    _root["warpframe"] = false;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope.self["warp1"]["hitTest"](_root["Course"]["Char"]["charClip"]["feet"])) {
            _root["Course"]["Char"]["attack"] = true;
            _root["Course"]["Char"]["xspeed"] = 0;
            _root["Course"]["Char"]["yspeed"] = 0;
            _root["Course"]["Char"]["attackFrame"] = "none";
            scope["warp"] = true;
            scope["warpnum"] = 1;
        }
        if (scope["warp"] == true && _root["warpframe"] == false) {
            if (scope["warpnum"] == 1) {
                _root["attachMovie"]("downtransition", "downtransition" + _root["getNextHighestDepth"](), _root["getNextHighestDepth"](), obj({{"_x", _root["screensizeX"] / 2}, {"_y", _root["screensizeY"] / 2}}));
            }
            scope["warp"] = false;
        }
        if (_root["warpframe"] == true) {
            if (scope["warpnum"] == 1) {
                _root["changecourse"]("downtransition2", "4-10", -1350, -600, -1350, -600);
            }
            //_root.warpframe = false;
        }
        return undefined;
    });
}

