// onClipEvent(load)
void clip_4429_34_0(Activation& scope) {
    if (_root["lvl4YellowSwitch"] == true) {
        scope["activated"] = true;
    }
    scope["Switchfunction"] = scope.function([](Activation& scope) -> Value {
        _root["lvl4YellowSwitch"] = true;
        scope["count"] = 0;
        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
            scope["count"]++;
            if (scope["count"] > 5 && _root["Course"]["Char"]["air"] == false) {
                scope["count"] = 0;
                //
                _root["PlayMessage"]("Ghost: NOO!!  The Second Ghost Switch has been activated!  Quick! Ghost Squad assemble at the East Tower Chamber!");
                scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                    //
                    _root["playpause"] = true;
                    //
                    scope["count"]++;
                    if ((_root["KeySPACE"]() || _root["KeyZ"]() || _root["KeyX"]()) && scope["count"] > 5) {
                        _root["StopMessage"]();
                        //
                        scope["count"] = 0;
                        scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
                            scope["count"]++;
                            if (scope["count"] > 5) {
                                _root["playpause"] = false;
                                _root["Course"]["Char"]["attack"] = false;
                                scope["onEnterFrame"] = Value::null();
                                gotoAndStop("end");
                            }
                            return undefined;
                        });
                    }
                    return undefined;
                });
            }
            return undefined;
        });
        return undefined;
    });
}

