// onClipEvent(enterFrame)
void clip_4429_60_1(Activation& scope) {
    if (scope["count"] > 5) {
        if (_root["PauseGame"] == false && _root["playpause"] == false) {
            if (scope.self["hitTest"](_root["Course"]["Char"]["charClip"]["body"]) && _root["Course"]["Char"]["yspeed"] <= 3 && _root["Course"]["Char"]["air"] == true) {
                _root["Course"]["Char"]["yspeed"] = _root["groundFriction"](_root["Course"]["Char"]["yspeed"], 0.035, 1.005);
                //_root.Course.Char.yspeed += 1;
                //_root.Course.Char.xspeed += 0.3;
            } else if (scope.self["hitTest"](_root["Course"]["Char"]["charClip"]["body"]) && _root["Course"]["Char"]["air"] == true) {
                _root["Course"]["Char"]["yspeed"] = _root["groundFriction"](_root["Course"]["Char"]["yspeed"], 0.035, 1.005);
                _root["Course"]["Char"]["yspeed"] += 1;
                //_root.Course.Char.xspeed += 0.1;
            }
        }
    } else {
        scope["count"]++;
    }
}

